<script setup lang="ts">
import { ref, onMounted } from 'vue'
import { request, query, type Page } from '../api'
import { dateTime } from '../domain.js'
import StatusBadge from './StatusBadge.vue'
import Modal from './Modal.vue'
const rows=ref<any[]>([]),total=ref(0),page=ref(1),status=ref('pending'),loading=ref(false),busy=ref(false),error=ref(''),success=ref(''),current=ref<any>(null),decision=ref('published')
async function load(){loading.value=true;error.value='';try{const result=await request<Page>('/admin/comments'+query({page:page.value,page_size:10,status:status.value}));rows.value=result.items;total.value=result.total}catch(err){error.value=(err as Error).message}finally{loading.value=false}}
async function review(){busy.value=true;error.value='';try{await request(`/comments/${current.value.id}/review`,{method:'POST',body:JSON.stringify({status:decision.value})});current.value=null;success.value='评论审核已保存';await load()}catch(err){error.value=(err as Error).message}finally{busy.value=false}}
onMounted(load)
</script>
<template><div class="page-heading"><div><h1>评论审核</h1><p>人工审核用户评论；AI审核服务未配置时不表示自动审查完成。</p></div><button class="button" @click="load">刷新评论</button></div><p v-if="error&&!current" class="notice danger" role="alert">{{ error }}</p><p v-if="success" class="notice success" role="status">{{ success }}</p><section class="panel"><form class="filter-bar" @submit.prevent="page=1;load()"><select v-model="status" aria-label="评论状态"><option value="">全部状态</option><option value="pending">待审核</option><option value="published">已发布</option><option value="rejected">已驳回</option></select><button class="button">查询</button><span class="record-count">共 {{ total }} 条评论</span></form><div class="table-scroll"><table><thead><tr><th>编号</th><th>帖子 / 用户</th><th>评论内容</th><th>状态</th><th>时间</th><th>操作</th></tr></thead><tbody><tr v-if="loading"><td colspan="6" class="empty">正在加载…</td></tr><tr v-else-if="!rows.length"><td colspan="6" class="empty">暂无评论</td></tr><tr v-for="row in rows" v-else :key="row.id"><td>#{{ row.id }}</td><td>帖子 #{{ row.post_id }} / 用户 #{{ row.user_id }}</td><td class="cell-truncate">{{ row.content }}</td><td><StatusBadge :value="row.status" /></td><td>{{ dateTime(row.created_at) }}</td><td><button class="text-button" @click="current=row;decision='published';error=''">{{ row.status==='pending'?'审核评论':'查看评论' }}</button></td></tr></tbody></table></div><div class="pagination"><span>第 {{ page }} 页</span><button class="button small" :disabled="page<=1||loading" @click="page--;load()">上一页</button><button class="button small" :disabled="page*10>=total||loading" @click="page++;load()">下一页</button></div></section><Modal v-if="current" title="用户评论" @close="!busy&&(current=null)"><p v-if="error" class="notice danger" role="alert">{{ error }}</p><p class="notice preserve-lines">{{ current.content }}</p><form v-if="current.status==='pending'" id="comment-review" @submit.prevent="review"><label><span>审核结果</span><select v-model="decision"><option value="published">审核通过并发布</option><option value="rejected">驳回</option></select></label></form><template #footer><button class="button" :disabled="busy" @click="current=null">关闭</button><button v-if="current.status==='pending'" class="button primary" form="comment-review" :disabled="busy">{{ busy?'正在保存…':'保存审核结果' }}</button></template></Modal></template>
